/* Local QRCode fallback for Uti-Mate: no CDN required. Supports QR byte mode, version 10, low EC. */
(function(){
  'use strict';
  const VERSION=10, SIZE=57, DATA_CODEWORDS=274, TOTAL_CODEWORDS=346, ECC_PER_BLOCK=18, NUM_BLOCKS=4;
  function gfMul(x,y){let z=0;for(let i=7;i>=0;i--){z=((z<<1)^(((z>>>7)&1)*0x11D))&255;if(((y>>>i)&1)!==0)z^=x;}return z&255;}
  function rsGen(deg){const res=new Array(deg).fill(0);res[deg-1]=1;let root=1;for(let i=0;i<deg;i++){for(let j=0;j<res.length;j++){res[j]=gfMul(res[j],root);if(j+1<res.length)res[j]^=res[j+1];}root=gfMul(root,2);}return res;}
  function rsRemainder(data,deg){const gen=rsGen(deg), res=new Array(deg).fill(0);for(const b of data){const factor=b^res.shift();res.push(0);for(let i=0;i<deg;i++)res[i]^=gfMul(gen[i],factor);}return res;}
  class BitBuffer{constructor(){this.bits=[];} append(val,len){for(let i=len-1;i>=0;i--)this.bits.push((val>>>i)&1);} get length(){return this.bits.length;} toBytes(){const out=[];for(let i=0;i<this.bits.length;i+=8){let b=0;for(let j=0;j<8;j++)b=(b<<1)|(this.bits[i+j]||0);out.push(b);}return out;}}
  function encodeData(text){const data=new TextEncoder().encode(String(text||''));if(data.length>271)throw new Error('Text is too long for this browser QR generator. Keep it below 271 bytes.');const bb=new BitBuffer();bb.append(4,4);bb.append(data.length,16);for(const b of data)bb.append(b,8);bb.append(0,Math.min(4,DATA_CODEWORDS*8-bb.length));while(bb.length%8)bb.append(0,1);const bytes=bb.toBytes();for(let pad=0;bytes.length<DATA_CODEWORDS;pad^=1)bytes.push(pad?0x11:0xEC);return bytes;}
  function makeCodewords(data){const blocks=[];const shortLen=Math.floor(TOTAL_CODEWORDS/NUM_BLOCKS)-ECC_PER_BLOCK;const numShort=NUM_BLOCKS-(TOTAL_CODEWORDS%NUM_BLOCKS);let k=0;for(let i=0;i<NUM_BLOCKS;i++){const datLen=shortLen+(i>=numShort?1:0);const dat=data.slice(k,k+datLen);k+=datLen;blocks.push({data:dat,ecc:rsRemainder(dat,ECC_PER_BLOCK)});}const result=[];const maxDat=Math.max(...blocks.map(b=>b.data.length));for(let i=0;i<maxDat;i++)for(const b of blocks)if(i<b.data.length)result.push(b.data[i]);for(let i=0;i<ECC_PER_BLOCK;i++)for(const b of blocks)result.push(b.ecc[i]);return result;}
  function newMatrix(){return {m:Array.from({length:SIZE},()=>Array(SIZE).fill(false)),f:Array.from({length:SIZE},()=>Array(SIZE).fill(false))};}
  function setFunc(q,x,y,dark){if(x>=0&&y>=0&&x<SIZE&&y<SIZE){q.m[y][x]=!!dark;q.f[y][x]=true;}}
  function drawFinder(q,x,y){for(let dy=-1;dy<=7;dy++)for(let dx=-1;dx<=7;dx++){const xx=x+dx,yy=y+dy;if(xx<0||yy<0||xx>=SIZE||yy>=SIZE)continue;const dark=dx>=0&&dx<=6&&dy>=0&&dy<=6&&(dx===0||dx===6||dy===0||dy===6||(dx>=2&&dx<=4&&dy>=2&&dy<=4));setFunc(q,xx,yy,dark);}}
  function drawAlign(q,cx,cy){for(let dy=-2;dy<=2;dy++)for(let dx=-2;dx<=2;dx++)setFunc(q,cx+dx,cy+dy,Math.max(Math.abs(dx),Math.abs(dy))!==1);}
  function reserveFormat(q){for(let i=0;i<9;i++){if(i!==6){setFunc(q,8,i,false);setFunc(q,i,8,false);}}for(let i=0;i<8;i++){setFunc(q,SIZE-1-i,8,false);setFunc(q,8,SIZE-1-i,false);}}
  function drawFunctionPatterns(q){drawFinder(q,0,0);drawFinder(q,SIZE-7,0);drawFinder(q,0,SIZE-7);for(let i=8;i<SIZE-8;i++){setFunc(q,i,6,i%2===0);setFunc(q,6,i,i%2===0);}const pos=[6,28,50];for(const y of pos)for(const x of pos)if(!((x===6&&y===6)||(x===6&&y===50)||(x===50&&y===6)))drawAlign(q,x,y);reserveFormat(q);for(let i=0;i<6;i++)for(let j=0;j<3;j++){setFunc(q,SIZE-11+j,i,false);setFunc(q,i,SIZE-11+j,false);}setFunc(q,8,4*VERSION+9,true);}
  function getBit(x,i){return ((x>>>i)&1)!==0;}
  function bchFormat(ecl,mask){let data=(ecl<<3)|mask;let rem=data<<10;for(let i=14;i>=10;i--)if(getBit(rem,i))rem^=0x537<<(i-10);return ((data<<10)|rem)^0x5412;}
  function bchVersion(ver){let rem=ver<<12;for(let i=17;i>=12;i--)if(getBit(rem,i))rem^=0x1F25<<(i-12);return (ver<<12)|rem;}
  function drawFormat(q,mask){const bits=bchFormat(1,mask);for(let i=0;i<=5;i++)setFunc(q,8,i,getBit(bits,i));setFunc(q,8,7,getBit(bits,6));setFunc(q,8,8,getBit(bits,7));setFunc(q,7,8,getBit(bits,8));for(let i=9;i<15;i++)setFunc(q,14-i,8,getBit(bits,i));for(let i=0;i<8;i++)setFunc(q,SIZE-1-i,8,getBit(bits,i));for(let i=8;i<15;i++)setFunc(q,8,SIZE-15+i,getBit(bits,i));setFunc(q,8,SIZE-8,true);}
  function drawVersion(q){const bits=bchVersion(VERSION);for(let i=0;i<18;i++){const dark=getBit(bits,i);const a=SIZE-11+(i%3), b=Math.floor(i/3);setFunc(q,a,b,dark);setFunc(q,b,a,dark);}}
  function placeData(q,cw){let bits=[];for(const b of cw)for(let i=7;i>=0;i--)bits.push((b>>>i)&1);let idx=0,up=true;for(let right=SIZE-1;right>=1;right-=2){if(right===6)right--;for(let vert=0;vert<SIZE;vert++){const y=up?SIZE-1-vert:vert;for(let j=0;j<2;j++){const x=right-j;if(q.f[y][x])continue;let dark=(idx<bits.length)&&bits[idx++]===1;if(((x+y)&1)===0)dark=!dark;q.m[y][x]=dark;}}up=!up;}}
  function createMatrix(text){const q=newMatrix();drawFunctionPatterns(q);placeData(q,makeCodewords(encodeData(text)));drawFormat(q,0);drawVersion(q);return q.m;}
  function drawCanvas(canvas,text,opts){opts=opts||{};const width=opts.width||256,margin=opts.margin==null?4:opts.margin;canvas.width=width;canvas.height=width;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,width,width);const mat=createMatrix(text);const scale=width/(SIZE+margin*2);ctx.fillStyle='#000';for(let y=0;y<SIZE;y++)for(let x=0;x<SIZE;x++)if(mat[y][x])ctx.fillRect(Math.round((x+margin)*scale),Math.round((y+margin)*scale),Math.ceil(scale),Math.ceil(scale));}
  window.QRCode={toCanvas:function(canvas,text,opts,cb){return new Promise((resolve,reject)=>{try{drawCanvas(canvas,text,opts||{});if(typeof cb==='function')cb(null);resolve();}catch(e){if(typeof cb==='function')cb(e);reject(e);}});}};
})();
